package webpresenter.protocol;

import java.util.List;

/**
 * Every message exchanged between the central server and a MediaPlayer. Each record is the payload
 * of an {@link Envelope}; its wire name comes from {@link MessageType}.
 */
public sealed interface Message {

    // ------------------------------------------------------------------ player → server

    /**
     * First message after the connection opens.
     *
     * @param deviceId persistent id generated by the player on first start
     * @param hostname host name, used as the default device name
     * @param token device token received in {@link Paired}, or null if not paired yet
     */
    record Hello(String deviceId, String hostname, String playerVersion, int protocolVersion,
            List<DisplayInfo> displays, String token) implements Message {

        public Hello {
            displays = displays == null ? List.of() : List.copyOf(displays);
        }
    }

    /**
     * Download progress of everything the player must keep in its cache: the rest screen plus the
     * media of the prepared event. Files are counted once even if used by several items.
     *
     * @param eventId event of the last {@link Prepare} this status covers, or null if none
     * @param itemsFailed files whose download or verification failed (retried on the next PREPARE)
     */
    record CacheStatus(String eventId, int itemsReady, int itemsTotal, int itemsFailed, long bytesReady,
            long bytesTotal) implements Message {

        public boolean complete() {
            return itemsReady == itemsTotal && itemsFailed == 0;
        }
    }

    /**
     * What the player is showing, sent when it changes and about once per second while media plays.
     *
     * @param itemId item of the prepared event, or null for the rest screen
     * @param positionMs playback position (0 for images and slides)
     * @param durationMs media duration if known, otherwise 0
     * @param detail human-readable reason when {@code status} is FAILED
     */
    record PlaybackState(String itemId, PlaybackStatus status, long positionMs, long durationMs, String detail,
            Integer slide) implements Message {

        public PlaybackState(String itemId, PlaybackStatus status, long positionMs, long durationMs, String detail) {
            this(itemId, status, positionMs, durationMs, detail, null);
        }
    }

    // ------------------------------------------------------------------ server → player

    /** The device is waiting for operator approval; the player shows the code on screen. */
    record PairingPending(String pairingCode) implements Message {}

    /** The operator approved the device. The player stores the token and sends it in every {@link Hello}. */
    record Paired(String token) implements Message {}

    /**
     * Device settings chosen by the operator. Sent after a successful {@link Hello} and whenever they change.
     *
     * @param displayIndex index of the display used for the presentation window
     * @param restScreen media shown while nothing is playing, or null for a black screen
     */
    record Config(String deviceName, int displayIndex, MediaRef restScreen, Transition transition) implements Message {}

    /**
     * The event the player must be ready to present: all its media must be downloaded before it
     * goes live. Sent on connection and whenever the current event or its items change.
     *
     * @param eventId null when there is no current event (the player may drop event media)
     * @param items in presentation order
     */
    record Prepare(String eventId, String title, List<PlanItem> items, BackgroundMusic rest) implements Message {

        public Prepare {
            items = items == null ? List.of() : List.copyOf(items);
        }

        public Prepare(String eventId, String title, List<PlanItem> items) {
            this(eventId, title, items, null);
        }

        public static Prepare none() {
            return new Prepare(null, null, List.of(), null);
        }

        /** With no current event: only the rest screen's background music (platform default). */
        public static Prepare none(BackgroundMusic rest) {
            return new Prepare(null, null, List.of(), rest);
        }
    }

    /**
     * Present an item of the prepared event.
     *
     * @param startAt instant at which to start, so several players start together
     * @param startPositionMs where to start in a video or audio (non-zero when joining mid-item)
     * @param slide song slide to start at (songs only; null = from the beginning)
     */
    record Play(String eventId, String itemId, java.time.Instant startAt, long startPositionMs, Transition transition,
            Integer slide) implements Message {

        public Play(String eventId, String itemId, java.time.Instant startAt, long startPositionMs, Transition transition) {
            this(eventId, itemId, startAt, startPositionMs, transition, null);
        }
    }

    /**
     * Show a slide of the song on screen. With the song's audio playing, the audio jumps to that
     * slide's cue (when it has one), so lyrics and recording stay in sync.
     */
    record ShowSlide(String itemId, int slide) implements Message {}

    /** Pause the current video or audio. */
    record Pause() implements Message {}

    /** Resume after {@link Pause}. */
    record Resume() implements Message {}

    /**
     * Audio levels and fades, the same for every player. Sent after a successful {@link Hello} and
     * whenever they change (also live, from the operator's mixer).
     *
     * @param master overall level 0..100, applied to every channel
     * @param media videos, audio files and songs 0..100
     * @param background background music 0..100
     * @param effects timer signals and other effects 0..100
     * @param fadeInMs background music fade in (also when it comes back after an item with sound)
     * @param fadeOutMs background music fade out (also before an item with sound)
     * @param duckPercent background level while an item with sound plays, in percent of its level;
     *     0 stops it (fade out, then pause)
     */
    record Mixer(int master, int media, int background, int effects, int fadeInMs, int fadeOutMs, int duckPercent)
            implements Message {

        public static Mixer defaults() {
            return new Mixer(100, 100, 60, 100, 2000, 1500, 0);
        }
    }

    /** Stop whatever is presented and show the rest screen. */
    record ShowRest(Transition transition) implements Message {}

    /** The device was removed by an operator; the player forgets its token. */
    record Revoked(String reason) implements Message {}

    // ------------------------------------------------------------------ both directions

    record Error(String code, String message) implements Message {}

    // ------------------------------------------------------------------ value types

    /** A display reported by the player. Sizes are in logical pixels; {@code scale} converts to physical. */
    record DisplayInfo(int index, int width, int height, double scale, boolean primary) {}

    /** A media file the player must download (and verify) before showing it. */
    record MediaRef(String mediaId, MediaKind kind, String url, String sha256, long sizeBytes) {}

    /** One step of an event: a media file, a text slide, or a song rendered by the player. */
    /**
     * @param background music played while this item shows when it has no sound of its own (slides,
     *     images, songs without audio); null = silence. Items with sound duck or stop it.
     */
    record PlanItem(String itemId, ItemType type, String title, MediaRef media, Slide slide, SongContent song,
            BackgroundMusic background) {

        public PlanItem(String itemId, ItemType type, String title, MediaRef media, Slide slide) {
            this(itemId, type, title, media, slide, null, null);
        }

        public PlanItem(String itemId, ItemType type, String title, MediaRef media, Slide slide, SongContent song) {
            this(itemId, type, title, media, slide, song, null);
        }
    }

    /**
     * Music played softly behind items without sound and the rest screen: one track or a playlist,
     * looped.
     *
     * @param key identifies the source ("playlist:&lt;id&gt;", "media:&lt;id&gt;"); when consecutive items
     *     have the same key the music goes on instead of starting over
     * @param tracks audio files, downloaded with the rest of the event
     * @param shuffle play the tracks in random order
     */
    record BackgroundMusic(String key, List<MediaRef> tracks, boolean shuffle) {

        public BackgroundMusic {
            tracks = tracks == null ? List.of() : List.copyOf(tracks);
        }
    }

    /**
     * A song as the player presents it: lyrics slides over a background, optionally with audio
     * that advances the slides by itself.
     *
     * @param audio recording to play, or null (the operator advances slides)
     * @param cues start of each slide in the audio (ms), null entries for slides without a cue;
     *     empty without audio or timing
     * @param background image or video behind the lyrics, or null for the default background
     */
    record SongContent(String title, List<SongSlide> slides, MediaRef audio, List<Long> cues, MediaRef background) {

        public SongContent {
            slides = slides == null ? List.of() : List.copyOf(slides);
            cues = cues == null ? List.of() : java.util.Collections.unmodifiableList(new java.util.ArrayList<>(cues));
        }
    }

    record SongSlide(String label, boolean instrumental, List<String> lines, String cue) {

        public SongSlide {
            lines = lines == null ? List.of() : List.copyOf(lines);
        }
    }

    record Slide(String title, String body) {}

    enum ItemType { MEDIA, SLIDE, SONG }

    enum PlaybackStatus {
        /** Downloading or opening the item. */
        LOADING,
        /** Video or audio playing. */
        PLAYING,
        PAUSED,
        /** Image or slide on screen. */
        SHOWING,
        /** Video or audio reached its end; the player went back to the rest screen. */
        ENDED,
        /** Rest screen on screen. */
        REST,
        FAILED
    }

    record Transition(TransitionType type, int durationMs) {

        public static final Transition DEFAULT = new Transition(TransitionType.FADE, 600);
    }

    enum MediaKind { VIDEO, AUDIO, IMAGE }

    enum TransitionType { CUT, FADE }
}
